#ifndef __BC_MODELS_H__
#define __BC_MODELS_H__

#include <stdint.h>
#include <stdbool.h>
#include <stddef.h>

struct cJSON;

/* The AI-model catalog, generated by tools/gen_models.py and embedded into the binary
 * (//src/common:models_catalog_embedded_c). Read-only lookup for the first-run wizard
 * and the model picker: the providers on offer and, per provider, its models with their
 * context / output limits.
 *
 * Loaded lazily on the first call. The EMBEDDED copy is the default; the env var
 * EDGECLAW_MODELS_CATALOG can point at a file instead (dev / tests). All returned
 * pointers are borrowed and stay valid until edc_models_reset(). */

extern size_t edc_models_load(void);
extern const char *edc_models_source(void); /* "<embedded>" or the file path */
extern void edc_models_reset(void);         /* free; the next call reloads */

/* Providers, sorted by id. */
extern size_t edc_models_provider_count(void);
extern const char *edc_models_provider_id(size_t index);
extern const char *edc_models_provider_name(const char *provider_id);
extern const char *edc_models_provider_api(const char *provider_id); /* base URL */
/* The provider's API-key env var names (a JSON array, e.g. ["OPENAI_API_KEY"]), or NULL. */
extern const struct cJSON *edc_models_provider_env(const char *provider_id);

/* The provider's model ids, in catalog order (already sorted). */
extern size_t edc_models_model_count(const char *provider_id);
extern const char *edc_models_model_id_at(const char *provider_id, size_t index);

/* Facts about a model id (the metadata table is shared across providers). |out| may be
 * NULL to just test existence. */
struct edc_model_info
{
    const char *id;
    const char *name;
    int64_t context; /* tokens; 0 = unknown */
    int64_t output;
    bool tool_call;
    bool reasoning;
    bool attachment;
};
extern bool edc_models_model_info(const char *model_id, struct edc_model_info *out);

/* Case-insensitive substring match, for the wizard's filter boxes. An empty/NULL query
 * matches everything. */
extern bool edc_models_provider_matches(const char *provider_id, const char *query);
extern bool edc_models_model_matches(const char *model_id, const char *query);

/* Whether a model is chat-capable: `tool_call`, or "text" in its modalities. The wizard
 * lists only these, so embeddings / audio / image models stay out. */
extern bool edc_models_is_chat_model(const char *model_id);

/* The provider's i-th API-key env var name (e.g. "OPENAI_API_KEY"), or NULL. Lets the
 * frontend name the expected variable without a JSON dependency. */
extern const char *edc_models_provider_env_name(const char *provider_id, size_t index);

#endif
